args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?bd ?label WHERE {
  VALUES ?person { dbr:Thomas_Praytor dbr:Matthew_Knox }
  OPTIONAL { ?person dbo:birthDate ?birthDate . }
  OPTIONAL { ?person dbp:birthDate ?birthDate2 . }
  BIND(coalesce(?birthDate, ?birthDate2) AS ?bd)
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
}
ORDER BY DESC(?bd)
LIMIT 1

